import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import { color, uniform, positionLocal, mul, add } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    InstancedMesh,
    IcosahedronGeometry,
    PlaneGeometry,
    Object3D,
    DirectionalLight,
    AmbientLight,
    Color,
    Fog,
    AdditiveBlending,
  } = THREE;

  const group = new Group();
  group.name = config.id || 'particle-constellation-hero';

  const colors = config.intent?.visualSpec?.colors || {};
  const C_BG = colors.background || '#0b0b10';
  const C_INK = colors.ink || '#16161d';
  const C_PAPER = colors.paper || '#e8ecf2';
  const C_ACCENT = colors.accent || '#ff2a38';

  const timelines = [];
  const primitiveResults = [];
  const disposables = [];

  // ---------- STAGE BACKDROP (vertical gradient) ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const topCol = new Color(C_INK);
  const botCol = new Color(C_BG);
  // vertical gradient via local Y (plane spans -3..3)
  const tY = add(mul(positionLocal.y, 1 / 6), 0.5);
  backdropMat.colorNode = add(
    mul(color(botCol), add(mul(tY, -1), 1)),
    mul(color(topCol), tY)
  );
  backdropMat.fog = false;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- LIGHTS ----------
  const rim = new DirectionalLight(new Color(C_ACCENT), 0.8);
  rim.position.set(-3, 2, -1);
  group.add(rim);
  const fill = new AmbientLight(new Color(C_PAPER), 0.3);
  group.add(fill);

  // ---------- FIELD PARTICLES ----------
  const FIELD_COUNT = 1110;
  const CORE_COUNT = 90;
  const dummy = new Object3D();

  const fieldGeo = new IcosahedronGeometry(0.012, 0);
  const fieldMat = new MeshStandardNodeMaterial();
  fieldMat.color = new Color(C_PAPER);
  fieldMat.metalness = 0;
  fieldMat.roughness = 1;
  fieldMat.emissive = new Color(C_PAPER);
  fieldMat.emissiveIntensity = 0.9;
  fieldMat.transparent = true;
  const fieldMesh = new InstancedMesh(fieldGeo, fieldMat, FIELD_COUNT);
  fieldMesh.frustumCulled = false;
  disposables.push(fieldGeo, fieldMat);

  // anchors: ellipsoidal shell 6 x 4 x 5 centered at [0,0,-1.5]
  const fieldAnchors = [];
  const fieldPhase = [];
  const fieldColor = new Color(C_PAPER);
  for (let i = 0; i < FIELD_COUNT; i++) {
    // random point inside ellipsoid
    let x, y, z, r;
    do {
      x = Math.random() * 2 - 1;
      y = Math.random() * 2 - 1;
      z = Math.random() * 2 - 1;
      r = x * x + y * y + z * z;
    } while (r > 1);
    const ax = x * 3.0;
    const ay = y * 2.0;
    const az = z * 2.5 - 1.5;
    fieldAnchors.push({ x: ax, y: ay, z: az });
    fieldPhase.push(Math.random() * Math.PI * 2);
    // depth falloff opacity encoded in per-instance color brightness
    const zClamped = Math.max(-5, Math.min(0, az));
    const opacity = 0.9 + (zClamped / -5) * (0.15 - 0.9);
    fieldColor.copy(new Color(C_PAPER)).multiplyScalar(opacity);
    fieldMesh.setColorAt(i, fieldColor);
    dummy.position.set(ax, ay, az);
    dummy.scale.setScalar(0.001);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);
  }
  fieldMesh.instanceMatrix.needsUpdate = true;
  if (fieldMesh.instanceColor) fieldMesh.instanceColor.needsUpdate = true;
  group.add(fieldMesh);

  // ---------- ACCENT CORE PARTICLES ----------
  const coreGeo = new IcosahedronGeometry(0.012, 0);
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = new Color(C_ACCENT);
  coreMat.metalness = 0;
  coreMat.roughness = 1;
  coreMat.emissive = new Color(C_ACCENT);
  const coreEmissive = uniform(1.8);
  coreMat.emissiveNode = mul(color(new Color(C_ACCENT)), coreEmissive);
  coreMat.transparent = true;
  coreMat.blending = AdditiveBlending;
  coreMat.depthWrite = false;
  const coreMesh = new InstancedMesh(coreGeo, coreMat, CORE_COUNT);
  coreMesh.frustumCulled = false;
  disposables.push(coreGeo, coreMat);

  const coreAnchors = [];
  const corePhase = [];
  for (let i = 0; i < CORE_COUNT; i++) {
    let x, y, z, r;
    do {
      x = Math.random() * 2 - 1;
      y = Math.random() * 2 - 1;
      z = Math.random() * 2 - 1;
      r = x * x + y * y + z * z;
    } while (r > 1);
    const ax = x * 0.5;
    const ay = y * 0.5;
    const az = z * 0.5;
    coreAnchors.push({ x: ax, y: ay, z: az });
    corePhase.push(Math.random() * Math.PI * 2);
    dummy.position.set(ax, ay, az);
    dummy.scale.setScalar(0.001);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  group.add(coreMesh);

  // ---------- TEXT ----------
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const roleSizes = { hero: 96, subhead: 34, caption: 16 };
  const textObjects = [];
  for (const item of items) {
    const role = item.role || 'body';
    let size = roleSizes[role] || 24;
    let yPos = 0;
    let col = C_PAPER;
    let letter = 0;
    if (role === 'hero') {
      yPos = 0.5;
      col = C_PAPER;
    } else if (role === 'subhead') {
      yPos = -0.25;
    } else if (role === 'caption') {
      yPos = -2.25;
      col = C_ACCENT;
      letter = 1.5;
    }
    const txt = ctx.fontAtlas.createText(String(item.text || ''), {
      fontSize: size,
      color: col,
      align: 'center',
      letterSpacingPx: letter,
    });
    txt.position.set(0, yPos, 0.5);
    txt.traverse((o) => {
      if (o.material) o.material.fog = false;
    });
    group.add(txt);
    textObjects.push(txt);
  }

  // ---------- FOG ----------
  // fog applies at scene level; store cleanup to restore
  let addedFog = false;
  if (ctx.scene && !ctx.scene.fog) {
    ctx.scene.fog = new Fog(new Color(C_BG), 4, 10);
    addedFog = true;
  }

  // ---------- PRIMITIVE ----------
  const prims = config.cinematicPrimitives || [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      try {
        const res = fn(group, p.params || {});
        if (res) {
          primitiveResults.push(res);
          if (res.timeline) timelines.push(res.timeline);
        }
      } catch (e) {}
    }
  }

  // ---------- PARTICLE EMERGE (local) ----------
  const emergeProxy = { t: 0 };
  const emergeTl = gsap.timeline();
  emergeTl.to(emergeProxy, {
    t: 1,
    duration: 1.4,
    ease: 'expo.out',
    onUpdate() {
      const t = emergeProxy.t;
      for (let i = 0; i < FIELD_COUNT; i++) {
        const a = fieldAnchors[i];
        const s = Math.min(1, t);
        dummy.position.set(a.x * t, a.y * t, a.z * t);
        dummy.scale.setScalar(Math.max(0.001, s));
        dummy.updateMatrix();
        fieldMesh.setMatrixAt(i, dummy.matrix);
      }
      fieldMesh.instanceMatrix.needsUpdate = true;
      for (let i = 0; i < CORE_COUNT; i++) {
        const a = coreAnchors[i];
        const s = Math.min(1, t);
        dummy.position.set(a.x * t, a.y * t, a.z * t);
        dummy.scale.setScalar(Math.max(0.001, s));
        dummy.updateMatrix();
        coreMesh.setMatrixAt(i, dummy.matrix);
      }
      coreMesh.instanceMatrix.needsUpdate = true;
    },
  });
  timelines.push(emergeTl);

  // text entrances
  for (let i = 0; i < textObjects.length; i++) {
    const t = textObjects[i];
    const baseY = t.position.y;
    t.position.y = baseY + 0.4;
    const tl = gsap.timeline({ delay: 0.3 + i * 0.12 });
    tl.to(t.position, { y: baseY, duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  }

  // ---------- IDLE DRIFT + CORE PULSE ----------
  let elapsed = 0;
  const driftAmp = 0.04;
  const clock = { last: performance.now() };
  const tick = () => {
    const now = performance.now();
    const dt = (now - clock.last) / 1000;
    clock.last = now;
    elapsed += dt;

    if (emergeProxy.t >= 1) {
      const w = elapsed * Math.PI * 2 * 0.05;
      for (let i = 0; i < FIELD_COUNT; i++) {
        const a = fieldAnchors[i];
        const ph = fieldPhase[i];
        dummy.position.set(
          a.x + Math.sin(w + ph) * driftAmp,
          a.y + Math.cos(w + ph * 1.3) * driftAmp,
          a.z + Math.sin(w * 0.7 + ph) * driftAmp
        );
        dummy.scale.setScalar(1);
        dummy.updateMatrix();
        fieldMesh.setMatrixAt(i, dummy.matrix);
      }
      fieldMesh.instanceMatrix.needsUpdate = true;

      for (let i = 0; i < CORE_COUNT; i++) {
        const a = coreAnchors[i];
        const ph = corePhase[i];
        dummy.position.set(
          a.x + Math.sin(w + ph) * driftAmp,
          a.y + Math.cos(w + ph) * driftAmp,
          a.z + Math.sin(w * 0.8 + ph) * driftAmp
        );
        dummy.scale.setScalar(1);
        dummy.updateMatrix();
        coreMesh.setMatrixAt(i, dummy.matrix);
      }
      coreMesh.instanceMatrix.needsUpdate = true;
    }

    // core pulse 1.5 -> 1.8 at 0.1 Hz
    const pulse = 1.65 + 0.15 * Math.sin(elapsed * Math.PI * 2 * 0.1);
    coreEmissive.value = pulse;
  };

  group.userData.handlers = {
    update: tick,
  };

  group.userData.cleanup = () => {
    for (const tl of timelines) {
      try {
        tl.kill();
      } catch (e) {}
    }
    for (const r of primitiveResults) {
      try {
        r.cleanup && r.cleanup();
      } catch (e) {}
    }
    if (addedFog && ctx.scene) ctx.scene.fog = null;
    for (const d of disposables) {
      try {
        d.dispose && d.dispose();
      } catch (e) {}
    }
    try {
      fieldMesh.dispose && fieldMesh.dispose();
      coreMesh.dispose && coreMesh.dispose();
    } catch (e) {}
    for (const t of textObjects) {
      t.traverse((o) => {
        if (o.geometry) o.geometry.dispose && o.geometry.dispose();
        if (o.material) o.material.dispose && o.material.dispose();
      });
    }
  };

  return group;
}
